export class Renderer extends RendererCanvas {
	public app: Solution
	public time: number = 0.0;
	public pts: number[][] = [];
	constructor(div: any, app: Solution) {
		super(div);
		this.app = app;
		this.canvas.id = 'mapboxCustom'
		this.canvas.style.position = 'absolute';
		this.canvas.style.width = '100%';
		this.canvas.style.height = '100%';
		this.canvas.style.pointerEvents = 'none';

		// TODO
		// You code goes here for one time operation
		this.pts.push([-71.093161, 42.358871]);

		this.start();
	}
	public mouseDown = (x: number, y: number): void => {

	}
	public mouseUp = (x: number, y: number): void => {

	}
	public mouseDrag = (x: number, y: number): void => {

	}
	public render(ctx: CanvasRenderingContext2D): void {
		this.time += 0.1;

		for (let i = 0; i < this.pts.length; ++i) {
			const pt = this.pts[i];
			const p = this.app.mapboxWrapper.toScreen(pt[0], pt[1]);
			// const p = this.app.mapboxWrapper.map.unproject({x: 10, y: 10})

			ctx.beginPath();
			ctx.arc(p[0], p[1], Math.sin(this.time) * 3 + 15, 0, Math.PI * 2);
			ctx.closePath();
			ctx.fillStyle = '#0f0';
			ctx.fill();
		}

	}
}

class BoxCustomLayer {
	type = 'custom';
	renderingMode = '3d';
	id;

	map;
	camera;
	scene;
	ball;
	renderer;

	constructor(id) {
		this.id = id;
	}

	async onAdd(map, gl) {
		this.map = map;

		this.camera = new THREE.PerspectiveCamera(
			45,
			window.innerWidth / window.innerHeight,
			0.1,
			10000
		);

		this.scene = new THREE.Scene();
		const ambientLight = new THREE.AmbientLight(0xffffff, 0.8);
		this.scene.add(ambientLight);

		const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
		directionalLight.position.set(100, 100, 200);
		this.scene.add(directionalLight);

		const bostonLngLat = [-71.0589, 42.3601];
		const { MercatorCoordinate } = mapboxgl;
		const merc = MercatorCoordinate.fromLngLat(bostonLngLat, 0);

		const scale = merc.meterInMercatorCoordinateUnits();

		this.ball = new THREE.Mesh(
			new THREE.SphereGeometry(100 * scale, 32, 32),
			new THREE.MeshStandardMaterial({ color: 'blue' })
		);

		this.ball.position.set(merc.x, merc.y, merc.z);

		this.scene.add(this.ball);

		this.renderer = new THREE.WebGLRenderer({
			canvas: map.getCanvas(),
			context: gl,
			antialias: true,
		});
		this.renderer.autoClear = false;
	}

	render(gl, matrix) {
		this.camera.projectionMatrix = new THREE.Matrix4().fromArray(matrix);

		this.renderer.state.reset();
		this.renderer.clearDepth();
		this.renderer.render(this.scene, this.camera);

		this.map.triggerRepaint();
	}
}
